INSERT INTO std_lifestyle_plan (category_id,plan_type,plan_name,detail_json,evidence_level,created_by) VALUES
(19,'diet','Balanced Korean Diet Plan (80+, Male)','{"avoid": ["excessive alcohol", "sugary beverages", "late-night eating", "excessive sodium (>2000mg/day)"], "macros": {"fat_g": 47, "fat_pct": 25, "protein_g": 85, "protein_pct": 20, "carbohydrate_g": 234, "carbohydrate_pct": 55}, "guidelines": ["Half the plate should be vegetables (banchan)", "Include fermented foods daily (kimchi, doenjang)", "Limit processed foods and instant noodles", "Reduce sodium: use low-sodium soy sauce and gochujang", "Eat whole grains (brown rice, barley) instead of white rice", "Fish 2-3 times per week for omega-3"], "meal_pattern": {"lunch_pct": 35, "snack_pct": 10, "dinner_pct": 30, "breakfast_pct": 25, "meals_per_day": 3, "snacks_per_day": 1}, "micronutrients": {"iron_mg": 10, "calcium_mg": 1000, "fiber_g_min": 25, "sodium_mg_max": 2000, "vitamin_d_mcg": 15}, "daily_calories_kcal": 1700}'::jsonb,'A','Korean Nutrition Society DRIs 2020'),
(19,'exercise','Exercise Prescription (80+, Male)','{"precautions": ["Avoid high-impact activities", "Monitor heart rate during exercise", "Stop if chest pain or dizziness"], "aerobic_type": ["walking", "swimming", "cycling", "tai chi"], "resistance_type": ["bodyweight exercises", "resistance bands", "light dumbbells"], "balance_training": true, "aerobic_intensity": "moderate", "balance_exercises": ["single-leg stand", "heel-to-toe walk", "chair stand"], "rest_days_per_week": 3, "weekly_aerobic_min": 150, "weekly_resistance_days": 2, "flexibility_min_per_day": 10}'::jsonb,'A','ACSM Guidelines for Exercise Testing and Prescription, 11th Ed'),
(19,'sleep','Sleep Hygiene Plan (80+)','{"wake_window": "06:00-07:00", "target_hours": 7.0, "target_range": [6.5, 7.5], "hygiene_rules": ["No screens 1 hour before bed", "No caffeine after 14:00", "Keep bedroom temperature 18-20C", "No heavy meals within 3 hours of sleep", "Regular sleep/wake schedule (even weekends)", "Dark and quiet bedroom environment"], "bedtime_window": "22:00-23:00", "max_wake_count": 2, "rem_pct_target": 20, "sleep_quality_target": 7.0, "deep_sleep_pct_target": 15}'::jsonb,'A','Korean Sleep Society Guidelines + AASM'),
(19,'medication','Supplement Guidance (80+, Male)','{"conditional": [{"dose": 1000, "name": "Omega-3", "unit": "mg", "reason": "Cardiovascular protection (if not eating fish 2x/week)", "frequency": "daily"}], "recommended": [{"dose": 1000, "name": "Vitamin D", "unit": "IU", "reason": "Most Koreans are deficient (KNHANES: 75% < 20ng/mL)", "frequency": "daily"}, {"dose": 500, "name": "Calcium", "unit": "mg", "reason": "Bone density preservation", "frequency": "daily"}]}'::jsonb,'B','Korean Endocrine Society + Korean Nutrition Society'),
